{$ param title label="Heading" default="" description="Optional heading shown above the logos." $}
{$ param logo_1_src label="Logo 1 URL" default="" description="First logo image URL." type="fileurl" $}
{$ param logo_1_alt label="Logo 1 Alt" default="" description="First logo alt text." $}
{$ param logo_1_href label="Logo 1 Link" default="" description="First logo link (optional)." $}
{$ param logo_2_src label="Logo 2 URL" default="" description="Second logo image URL." type="fileurl" $}
{$ param logo_2_alt label="Logo 2 Alt" default="" description="Second logo alt text." $}
{$ param logo_2_href label="Logo 2 Link" default="" description="Second logo link (optional)." $}
{$ param logo_3_src label="Logo 3 URL" default="" description="Third logo image URL." type="fileurl" $}
{$ param logo_3_alt label="Logo 3 Alt" default="" description="Third logo alt text." $}
{$ param logo_3_href label="Logo 3 Link" default="" description="Third logo link (optional)." $}
{$ param logo_4_src label="Logo 4 URL" default="" description="Fourth logo image URL." type="fileurl" $}
{$ param logo_4_alt label="Logo 4 Alt" default="" description="Fourth logo alt text." $}
{$ param logo_4_href label="Logo 4 Link" default="" description="Fourth logo link (optional)." $}
{$ param logo_5_src label="Logo 5 URL" default="" description="Fifth logo image URL." type="fileurl" $}
{$ param logo_5_alt label="Logo 5 Alt" default="" description="Fifth logo alt text." $}
{$ param logo_5_href label="Logo 5 Link" default="" description="Fifth logo link (optional)." $}
{$ param logo_6_src label="Logo 6 URL" default="" description="Sixth logo image URL." type="fileurl" $}
{$ param logo_6_alt label="Logo 6 Alt" default="" description="Sixth logo alt text." $}
{$ param logo_6_href label="Logo 6 Link" default="" description="Sixth logo link (optional)." $}

<section class="ss-partner-strip mb-8 text-center">
  {$ if title $}<h3 class="ss-xsmall uppercase font-bold text-neutral-dark mb-4">{$= title $}</h3>{$ /if $}
  <div class="flex flex-wrap justify-center items-center gap-6">
    {$ if logo_1_src $}<a href="{$= logo_1_href $}" class="inline-block"><img src="{$= logo_1_src $}" alt="{$= logo_1_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
    {$ if logo_2_src $}<a href="{$= logo_2_href $}" class="inline-block"><img src="{$= logo_2_src $}" alt="{$= logo_2_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
    {$ if logo_3_src $}<a href="{$= logo_3_href $}" class="inline-block"><img src="{$= logo_3_src $}" alt="{$= logo_3_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
    {$ if logo_4_src $}<a href="{$= logo_4_href $}" class="inline-block"><img src="{$= logo_4_src $}" alt="{$= logo_4_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
    {$ if logo_5_src $}<a href="{$= logo_5_href $}" class="inline-block"><img src="{$= logo_5_src $}" alt="{$= logo_5_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
    {$ if logo_6_src $}<a href="{$= logo_6_href $}" class="inline-block"><img src="{$= logo_6_src $}" alt="{$= logo_6_alt $}" class="max-h-16 w-auto" /></a>{$ /if $}
  </div>
</section>
